project(medvision_runtime VERSION 0.1.0 LANGUAGES CXX)

set(CMAKE_CXX_STANDARD 20)
set(CMAKE_CXX_STANDARD_REQUIRED ON)
set(CMAKE_CXX_EXTENSIONS OFF)
set(CMAKE_BUILD_RPATH_USE_ORIGIN ON)
set(CMAKE_INSTALL_RPATH "\$ORIGIN;\$ORIGIN/../lib")

option(MEDVISION_WITH_ONNXRUNTIME "Build the ONNX Runtime backend" OFF)
option(MEDVISION_WITH_MEDIAPIPE "Build the MediaPipe face gate" OFF)
option(MEDVISION_WITH_OPENCV "Build image and video adapters" OFF)
option(MEDVISION_BUILD_HTTP "Build the HTTP inference service" OFF)
option(MEDVISION_BUILD_TESTS "Build C++ tests" ON)

add_library(medvision_core SHARED
    src/geometry.cpp
    src/postprocess.cpp
    src/face_gate.cpp
    src/face_regions.cpp
    src/single_device_tracker.cpp
)
add_library(medvision::core ALIAS medvision_core)
target_include_directories(medvision_core PUBLIC ${CMAKE_CURRENT_SOURCE_DIR}/include)
target_compile_features(medvision_core PUBLIC cxx_std_20)
if(CMAKE_CXX_COMPILER_ID MATCHES "GNU|Clang")
    target_compile_options(medvision_core PRIVATE -Wall -Wextra -Wpedantic -Werror)
endif()

if(MEDVISION_WITH_ONNXRUNTIME)
    if(NOT ONNXRUNTIME_ROOT)
        message(FATAL_ERROR "Set ONNXRUNTIME_ROOT to the extracted ONNX Runtime SDK")
    endif()
    find_path(ONNXRUNTIME_INCLUDE_DIR onnxruntime_cxx_api.h
        PATHS ${ONNXRUNTIME_ROOT}/include NO_DEFAULT_PATH REQUIRED)
    find_library(ONNXRUNTIME_LIBRARY onnxruntime
        PATHS ${ONNXRUNTIME_ROOT}/lib NO_DEFAULT_PATH REQUIRED)
    add_library(medvision_onnxruntime SHARED src/onnx_runtime_backend.cpp)
    add_library(medvision::onnxruntime ALIAS medvision_onnxruntime)
    target_include_directories(medvision_onnxruntime PRIVATE ${ONNXRUNTIME_INCLUDE_DIR})
    target_link_libraries(medvision_onnxruntime PUBLIC medvision_core ${ONNXRUNTIME_LIBRARY})
    target_compile_definitions(medvision_onnxruntime PUBLIC MEDVISION_WITH_ONNXRUNTIME=1)
    set_target_properties(medvision_onnxruntime PROPERTIES BUILD_RPATH "${ONNXRUNTIME_ROOT}/lib")
endif()

if(MEDVISION_WITH_MEDIAPIPE)
    if(NOT MEDIAPIPE_ROOT)
        message(FATAL_ERROR "Set MEDIAPIPE_ROOT to the MediaPipe source/header root")
    endif()
    if(NOT MEDIAPIPE_LIBRARY)
        message(FATAL_ERROR "Set MEDIAPIPE_LIBRARY to libmediapipe.so")
    endif()
    add_library(medvision_face_landmarker SHARED src/face_landmarker.cpp)
    add_library(medvision::face_landmarker ALIAS medvision_face_landmarker)
    target_include_directories(medvision_face_landmarker PRIVATE ${MEDIAPIPE_ROOT})
    target_link_libraries(medvision_face_landmarker PUBLIC medvision_core ${MEDIAPIPE_LIBRARY})
    get_filename_component(MEDIAPIPE_LIBRARY_DIR "${MEDIAPIPE_LIBRARY}" DIRECTORY)
    set_target_properties(medvision_face_landmarker PROPERTIES BUILD_RPATH "${MEDIAPIPE_LIBRARY_DIR}")
endif()

if(MEDVISION_WITH_OPENCV)
    if(NOT MEDVISION_WITH_ONNXRUNTIME OR NOT MEDVISION_WITH_MEDIAPIPE)
        message(FATAL_ERROR "MEDVISION_WITH_OPENCV requires ONNX Runtime and MediaPipe")
    endif()
    find_package(OpenCV CONFIG REQUIRED COMPONENTS core imgproc imgcodecs)
    find_package(apriltag CONFIG REQUIRED)
    find_package(yaml-cpp CONFIG REQUIRED)
    add_library(medvision_marker SHARED
        src/marker_detector.cpp
        src/marker_geometry.cpp
    )
    add_library(medvision::marker ALIAS medvision_marker)
    target_include_directories(medvision_marker PUBLIC include)
    target_link_libraries(medvision_marker PUBLIC
        medvision_core apriltag::apriltag yaml-cpp::yaml-cpp
        opencv_core opencv_imgproc opencv_imgcodecs)
    add_library(medvision_pipeline SHARED
        src/image_pipeline.cpp
        src/image_annotation.cpp
    )
    add_library(medvision::pipeline ALIAS medvision_pipeline)
    target_link_libraries(medvision_pipeline PUBLIC
        medvision_onnxruntime medvision_face_landmarker opencv_core opencv_imgproc opencv_imgcodecs)
endif()

add_executable(medvision_cli apps/medvision_cli.cpp)
target_link_libraries(medvision_cli PRIVATE medvision_core)
if(MEDVISION_WITH_ONNXRUNTIME)
    target_link_libraries(medvision_cli PRIVATE medvision_onnxruntime)
    set_target_properties(medvision_cli PROPERTIES BUILD_RPATH "${ONNXRUNTIME_ROOT}/lib")
endif()
if(MEDVISION_WITH_OPENCV)
    target_link_libraries(medvision_cli PRIVATE medvision_pipeline)
    add_executable(medvision_infer_image apps/medvision_infer_image.cpp)
    target_link_libraries(medvision_infer_image PRIVATE medvision_pipeline)
    set_target_properties(medvision_infer_image PROPERTIES
        BUILD_RPATH "${ONNXRUNTIME_ROOT}/lib;${MEDIAPIPE_LIBRARY_DIR}")
