    find_package(httplib CONFIG REQUIRED)
    find_package(nlohmann_json CONFIG REQUIRED)
    add_executable(medvision_http apps/medvision_http.cpp)
    target_link_libraries(medvision_http PRIVATE
        medvision_pipeline medvision_marker httplib::httplib nlohmann_json::nlohmann_json)
    set_target_properties(medvision_http PROPERTIES
        BUILD_RPATH "${ONNXRUNTIME_ROOT}/lib;${MEDIAPIPE_LIBRARY_DIR}")
    add_executable(medvision_marker_assets apps/medvision_marker_assets.cpp)
    target_link_libraries(medvision_marker_assets PRIVATE medvision_marker)
