namespace medvision {
namespace {

using Clock = std::chrono::steady_clock;

double elapsed_ms(Clock::time_point start) {
    return std::chrono::duration<double, std::milli>(Clock::now() - start).count();
}

Tensor detector_input(const cv::Mat& bgr, LetterboxTransform& transform) {
    constexpr int kSize = 640;
    const float ratio = std::min(
        static_cast<float>(kSize) / static_cast<float>(bgr.rows),
        static_cast<float>(kSize) / static_cast<float>(bgr.cols));
    const int resized_width = std::max(1, static_cast<int>(static_cast<float>(bgr.cols) * ratio));
    const int resized_height = std::max(1, static_cast<int>(static_cast<float>(bgr.rows) * ratio));
    cv::Mat resized;
    cv::resize(bgr, resized, {resized_width, resized_height}, 0.0, 0.0, cv::INTER_LINEAR);
    cv::Mat padded(kSize, kSize, CV_8UC3, cv::Scalar(114, 114, 114));
    resized.copyTo(padded(cv::Rect(0, 0, resized_width, resized_height)));

    Tensor tensor{{1, 3, kSize, kSize}, std::vector<float>(3U * kSize * kSize)};
    const std::size_t plane = static_cast<std::size_t>(kSize) * kSize;
    for (int y = 0; y < kSize; ++y) {
        const auto* row = padded.ptr<cv::Vec3b>(y);
        for (int x = 0; x < kSize; ++x) {
            const auto pixel = row[x];
            const auto offset = static_cast<std::size_t>(y) * kSize + static_cast<std::size_t>(x);
            tensor.values[offset] = static_cast<float>(pixel[0]);
            tensor.values[plane + offset] = static_cast<float>(pixel[1]);
            tensor.values[2U * plane + offset] = static_cast<float>(pixel[2]);
        }
    }
    transform = {bgr.cols, bgr.rows, kSize, kSize, ratio, 0.0F, 0.0F};
    return tensor;
}

BBox expanded_roi(const BBox& box, int width, int height, float ratio) {
    const float box_width = std::max(1.0F, box.x2 - box.x1);
    const float box_height = std::max(1.0F, box.y2 - box.y1);
    return {
        std::max(0.0F, std::floor(box.x1 - box_width * ratio)),
        std::max(0.0F, std::floor(box.y1 - box_height * ratio)),
        std::min(static_cast<float>(width), std::ceil(box.x2 + box_width * ratio)),
        std::min(static_cast<float>(height), std::ceil(box.y2 + box_height * ratio)),
    };
}

Tensor contact_input(const cv::Mat& bgr, const BBox& roi) {
    const int x1 = static_cast<int>(roi.x1);
    const int y1 = static_cast<int>(roi.y1);
    const int x2 = static_cast<int>(roi.x2);
    const int y2 = static_cast<int>(roi.y2);
    if (x2 <= x1 || y2 <= y1) {
        throw std::runtime_error("contact ROI is empty");
    }
    cv::Mat rgb;
    cv::cvtColor(bgr(cv::Rect(x1, y1, x2 - x1, y2 - y1)), rgb, cv::COLOR_BGR2RGB);
    cv::Mat resized;
    cv::resize(rgb, resized, {256, 256}, 0.0, 0.0, cv::INTER_LINEAR);

    constexpr float mean[3]{0.485F, 0.456F, 0.406F};
    constexpr float standard_deviation[3]{0.229F, 0.224F, 0.225F};
    Tensor tensor{{1, 3, 256, 256}, std::vector<float>(3U * 256U * 256U)};
    constexpr std::size_t plane = 256U * 256U;
    for (int y = 0; y < 256; ++y) {
        const auto* row = resized.ptr<cv::Vec3b>(y);
        for (int x = 0; x < 256; ++x) {
            const auto pixel = row[x];
            const auto offset = static_cast<std::size_t>(y) * 256U + static_cast<std::size_t>(x);
            for (std::size_t channel = 0; channel < 3; ++channel) {
                const float scaled = static_cast<float>(pixel[channel]) / 255.0F;
                tensor.values[channel * plane + offset] =
                    (scaled - mean[channel]) / standard_deviation[channel];
            }
        }
    }
    return tensor;
}

std::vector<float> softmax(const std::vector<float>& logits) {
    if (logits.empty()) {
        throw std::runtime_error("softmax input is empty");
    }
    const float maximum = *std::max_element(logits.begin(), logits.end());
    std::vector<float> probabilities(logits.size());
    float denominator{};
    for (std::size_t index = 0; index < logits.size(); ++index) {
        probabilities[index] = std::exp(logits[index] - maximum);
        denominator += probabilities[index];
    }
    if (!(denominator > 0.0F) || !std::isfinite(denominator)) {
        throw std::runtime_error("softmax denominator is not finite");
    }
    for (auto& probability : probabilities) {
        probability /= denominator;
    }
    return probabilities;
}

float heatmap_confidence(const std::vector<float>& logits) {
    const auto probabilities = softmax(logits);
    double entropy{};
    for (const float probability : probabilities) {
        if (probability > 0.0F) {
            entropy -= static_cast<double>(probability) * std::log(static_cast<double>(probability));
        }
    }
    const double normalized = entropy / std::log(static_cast<double>(std::max<std::size_t>(probabilities.size(), 2)));
    return std::clamp(static_cast<float>(1.0 - normalized), 0.0F, 1.0F);
}

ContactVisibility visibility_from_index(std::size_t index) {
    if (index == 0) {
        return ContactVisibility::Visible;
    }
    if (index == 1) {
        return ContactVisibility::OccludedInferable;
    }
    return ContactVisibility::NotAnnotatable;
}

