std::vector<DeviceDetection> decode_yolox(
    const std::vector<YoloXPrediction>& predictions,
    float score_threshold,
    float nms_iou_threshold,
    const LetterboxTransform& transform) {
    std::vector<DeviceDetection> candidates;
    for (const auto& prediction : predictions) {
        const float score = prediction.objectness * prediction.class_probability;
        if (score < score_threshold || prediction.width <= 0.0F || prediction.height <= 0.0F) {
            continue;
        }
        const BBox network_box{
            prediction.center_x - prediction.width * 0.5F,
            prediction.center_y - prediction.height * 0.5F,
            prediction.center_x + prediction.width * 0.5F,
            prediction.center_y + prediction.height * 0.5F,
        };
        candidates.push_back({from_letterbox(network_box, transform), score});
    }
    std::sort(candidates.begin(), candidates.end(), [](const auto& left, const auto& right) {
        return left.score > right.score;
    });
    std::vector<DeviceDetection> kept;
    for (const auto& candidate : candidates) {
        const bool suppressed = std::any_of(kept.begin(), kept.end(), [&](const auto& accepted) {
            return bbox_iou(candidate.bbox, accepted.bbox) > nms_iou_threshold;
        });
        if (!suppressed) {
            kept.push_back(candidate);
        }
    }
    return kept;
}

std::optional<Point2f> decode_heatmap_peak(
    const std::vector<float>& heatmap,
    std::size_t width,
    std::size_t height,
    const BBox& roi,
    float minimum_value) {
    if (width == 0 || height == 0 || heatmap.size() != width * height) {
        throw std::invalid_argument("heatmap dimensions do not match its values");
    }
    const auto peak = std::max_element(heatmap.begin(), heatmap.end());
    if (*peak < minimum_value) {
        return std::nullopt;
    }
    const std::size_t index = static_cast<std::size_t>(std::distance(heatmap.begin(), peak));
    const std::size_t peak_x = index % width;
    const std::size_t peak_y = index / width;
    const float roi_width = roi.x2 - roi.x1;
    const float roi_height = roi.y2 - roi.y1;
    return Point2f{
        roi.x1 + (static_cast<float>(peak_x) + 0.5F) * roi_width / static_cast<float>(width),
        roi.y1 + (static_cast<float>(peak_y) + 0.5F) * roi_height / static_cast<float>(height),
    };
}

Point2f decode_heatmap_peak_neighborhood(
    const std::vector<float>& heatmap_logits,
    std::size_t width,
    std::size_t height,
    const BBox& roi,
    std::size_t radius) {
    if (width == 0 || height == 0 || heatmap_logits.size() != width * height) {
        throw std::invalid_argument("heatmap dimensions do not match its values");
    }
    const auto peak = std::max_element(heatmap_logits.begin(), heatmap_logits.end());
    const std::size_t peak_index =
        static_cast<std::size_t>(std::distance(heatmap_logits.begin(), peak));
    const std::size_t peak_x = peak_index % width;
    const std::size_t peak_y = peak_index / width;
    const std::size_t start_x = peak_x > radius ? peak_x - radius : 0;
    const std::size_t end_x = std::min(width, peak_x + radius + 1);
    const std::size_t start_y = peak_y > radius ? peak_y - radius : 0;
    const std::size_t end_y = std::min(height, peak_y + radius + 1);

    double weight_sum = 0.0;
    double weighted_x = 0.0;
    double weighted_y = 0.0;
    const double maximum = static_cast<double>(*peak);
    for (std::size_t y = start_y; y < end_y; ++y) {
        for (std::size_t x = start_x; x < end_x; ++x) {
            const double weight =
                std::exp(static_cast<double>(heatmap_logits[y * width + x]) - maximum);
            weight_sum += weight;
            weighted_x += weight * static_cast<double>(x);
            weighted_y += weight * static_cast<double>(y);
        }
    }
    if (!(weight_sum > 0.0) || !std::isfinite(weight_sum)) {
        throw std::runtime_error("heatmap neighborhood softmax is not finite");
    }
    const double heatmap_x = weighted_x / weight_sum;
    const double heatmap_y = weighted_y / weight_sum;
    const double width_denominator =
        static_cast<double>(std::max<std::size_t>(width - 1, 1));
    const double height_denominator =
        static_cast<double>(std::max<std::size_t>(height - 1, 1));
    return Point2f{
        static_cast<float>(
            static_cast<double>(roi.x1)
            + heatmap_x / width_denominator * static_cast<double>(roi.x2 - roi.x1)),
        static_cast<float>(
            static_cast<double>(roi.y1)
            + heatmap_y / height_denominator * static_cast<double>(roi.y2 - roi.y1)),
    };
