std::uint64_t unsigned_header(const httplib::Request& request, const char* name, bool required = false) {
    const auto value = request.get_header_value(name);
    if (value.empty()) {
        if (required) throw std::invalid_argument(std::string("missing ") + name);
        return 0;
    }
    std::size_t consumed{};
    const auto parsed = std::stoull(value, &consumed);
    if (consumed != value.size()) throw std::invalid_argument(std::string("invalid ") + name);
    return parsed;
}

std::int64_t signed_header(const httplib::Request& request, const char* name, bool required = false) {
    const auto value = request.get_header_value(name);
    if (value.empty()) {
        if (required) throw std::invalid_argument(std::string("missing ") + name);
        return 0;
    }
    std::size_t consumed{};
    const auto parsed = std::stoll(value, &consumed);
    if (consumed != value.size()) throw std::invalid_argument(std::string("invalid ") + name);
    return parsed;
}

std::optional<double> double_header(const httplib::Request& request, const char* name) {
    const auto value = request.get_header_value(name);
    if (value.empty()) return std::nullopt;
    std::size_t consumed{};
    const double parsed = std::stod(value, &consumed);
    if (consumed != value.size() || !std::isfinite(parsed) || parsed < 0.0) {
        throw std::invalid_argument(std::string("invalid ") + name);
    }
    return parsed;
}

std::unordered_set<std::string> split_origins(const std::string& text) {
    std::unordered_set<std::string> origins;
    std::stringstream stream(text);
    std::string origin;
    while (std::getline(stream, origin, ',')) if (!origin.empty()) origins.insert(origin);
    return origins;
}

void apply_cors(const httplib::Request& request, httplib::Response& response,
