        stream << "\\r";
        break;
      case '\t':
        stream << "\\t";
        break;
      default:
        if (character < 0x20U) {
          const char* hex = "0123456789abcdef";
          stream << "\\u00" << hex[(character >> 4U) & 0x0FU]
                 << hex[character & 0x0FU];
        } else {
          stream << static_cast<char>(character);
        }
