  <script>
    const video = document.querySelector("#video");
    const view = document.querySelector("#view");
    const ctx = view.getContext("2d");
    const capture = document.createElement("canvas");
    const status = document.querySelector("#status");
    const startButton = document.querySelector("#start");
    const stopButton = document.querySelector("#stop");
    const captureDeviceButton = document.querySelector("#capture-device");
    const captureNegativeButton = document.querySelector("#capture-negative");
    const captureStopButton = document.querySelector("#capture-stop");
    const captureStatus = document.querySelector("#capture-status");
    let socket = null, stream = null, timer = null, captureTimer = null, raf = null;
    let frameId = 0, latest = null, responses = 0, windowStart = performance.now();
    let captureMode = null, captureBusy = false, captureCount = 0;

    function setStatus(text) { status.textContent = text; }
    function drawBox(box, color, label, dashed=false) {
      if (!box) return;
      const [x1, y1, x2, y2] = box;
      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = color === "#ff3030" ? 6 : 4;
      ctx.setLineDash(dashed ? [14, 9] : []);
      ctx.strokeRect(x1, y1, x2 - x1, y2 - y1);
      ctx.setLineDash([]);
      ctx.fillStyle = color;
      ctx.font = "bold 18px sans-serif";
      ctx.fillText(label, x1 + 5, Math.max(22, y1 + 22));
      ctx.restore();
    }
    function drawPoint(point, color, label) {
      if (!point) return;
      const [x, y] = point;
      const radius = Math.max(12, Math.min(view.width, view.height) * .018);
      ctx.strokeStyle = color; ctx.lineWidth = 5;
      ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x - radius - 6, y); ctx.lineTo(x + radius + 6, y);
      ctx.moveTo(x, y - radius - 6); ctx.lineTo(x, y + radius + 6);
      ctx.stroke();
      ctx.fillStyle = color; ctx.font = "bold 18px sans-serif";
      ctx.fillText(label, x + radius + 8, y + radius + 8);
    }
    function paint() {
      if (video.videoWidth) {
        if (view.width !== video.videoWidth || view.height !== video.videoHeight) {
          view.width = video.videoWidth; view.height = video.videoHeight;
          capture.width = view.width; capture.height = view.height;
        }
        ctx.drawImage(video, 0, 0, view.width, view.height);
        if (latest) {
          drawBox(latest.raw.face_roi, "#ffe25c", "人脸搜索区", true);
          drawBox(latest.raw.device.bbox, "#ff9218", "原始设备框");
          drawBox(latest.stable.device_bbox, "#ff3030", "稳定设备框");
          drawPoint(latest.raw.contact.point, "#ff2d9a", "原始接触点");
          drawPoint(latest.stable.contact_point, "#ff3030", "稳定接触点");
          if (latest.needs_review) {
            ctx.fillStyle = "#ffe25c"; ctx.font = "bold 24px sans-serif";
            ctx.fillText(latest.stale ? "短暂沿用，需要复查" : "需要复查", 14, 34);
          }
        }
      }
      raf = requestAnimationFrame(paint);
    }
    function jpegBlob(callback) {
      capture.getContext("2d").drawImage(video, 0, 0, capture.width, capture.height);
      capture.toBlob(callback, "image/jpeg", .92);
    }
    function captureFrame() {
      if (!socket || socket.readyState !== WebSocket.OPEN || !video.videoWidth) return;
      const id = frameId++;
      socket.send(JSON.stringify({type:"frame_meta", frame_id:id, source_timestamp_ms:Date.now()}));
      jpegBlob(function(blob) {
        if (blob && socket.readyState === WebSocket.OPEN) socket.send(blob);
      });
    }
    async function requestCamera() {
      const high = {video:{width:{ideal:1920},height:{ideal:1080},frameRate:{ideal:30}},audio:false};
      try { return await navigator.mediaDevices.getUserMedia(high); }
      catch (_) { return navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false}); }
    }
    async function enableContinuousFocus() {
      const track = stream && stream.getVideoTracks()[0];
      const capabilities = track && track.getCapabilities ? track.getCapabilities() : null;
      if (capabilities && capabilities.focusMode && capabilities.focusMode.includes("continuous")) {
        try { await track.applyConstraints({advanced:[{focusMode:"continuous"}]}); } catch (_) {}
      }
    }
    function updateCaptureButtons(active) {
      captureDeviceButton.disabled = !stream || active;
      captureNegativeButton.disabled = !stream || active;
      captureStopButton.disabled = !active;
    }
    function renderCaptureSummary(data) {
      const sessions = data.sessions || {device:0,no_device:0};
      const active = data.active_session
        ? `；当前 ${data.active_label === "device" ? "有设备" : "无设备"} ${data.active_count}/10`
        : "";
      captureStatus.textContent = `有设备 ${sessions.device || 0}/6 段；无设备 ${sessions.no_device || 0}/6 段${active}。`;
    }
    async function refreshCaptureStatus() {
      const response = await fetch("/v1/capture/session/status");
      const data = await response.json();
      if (data.ok) renderCaptureSummary(data);
    }
    async function start() {
      try {
        setStatus("正在请求摄像头权限。");
        stream = await requestCamera();
        video.srcObject = stream;
        await video.play();
        await enableContinuousFocus();
        const settings = stream.getVideoTracks()[0].getSettings();
        document.querySelector("#resolution").textContent =
          `${settings.width || video.videoWidth} × ${settings.height || video.videoHeight} / ${Math.round(settings.frameRate || 0)} FPS`;
        const scheme = location.protocol === "https:" ? "wss://" : "ws://";
        socket = new WebSocket(scheme + location.host + "/v1/stream/infer");
        socket.onmessage = function(event) {
          const message = JSON.parse(event.data);
          if (message.event === "connected") {
            document.querySelector("#provider").textContent = message.execution_provider;
            setStatus("摄像头已连接，正在接收推理结果。");
            return;
          }
          if (!message.ok) { setStatus("推理失败：" + message.error); return; }
          latest = message.result; responses++;
          document.querySelector("#latency").textContent = latest.timings_ms.end_to_end.toFixed(1) + " ms";
          document.querySelector("#dropped").textContent = latest.dropped_frames;
          const now = performance.now();
          if (now - windowStart >= 1000) {
            document.querySelector("#fps").textContent = responses;
            responses = 0; windowStart = now;
          }
        };
        socket.onerror = function() { setStatus("无法连接本机推理服务。"); };
        timer = setInterval(captureFrame, 100);
        raf = requestAnimationFrame(paint);
        startButton.disabled = true; stopButton.disabled = false;
        updateCaptureButtons(false);
      } catch (error) { setStatus("无法打开摄像头：" + error.message); }
    }
    async function startDatasetCapture(label) {
      if (!stream) { setStatus("请先启动摄像头。"); return; }
      try {
        const response = await fetch("/v1/capture/session/start", {
          method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({label})
        });
        const data = await response.json();
        if (!data.ok) { setStatus("无法开始采集：" + data.error); return; }
        captureMode = label; captureCount = 0;
        document.querySelector("#capture-count").textContent = "0/10";
        updateCaptureButtons(true);
        await refreshCaptureStatus();
        setStatus(`正在采集第 ${data.session_ordinal}/6 段${label === "device" ? "有设备画面" : "无设备背景"}，10 帧后自动停止。`);
        captureTimer = setInterval(captureDatasetFrame, 1000);
      } catch (error) { setStatus("采集启动失败：" + error.message); }
    }
    function captureDatasetFrame() {
      if (!captureTimer || captureBusy || !video.videoWidth) return;
      captureBusy = true;
"}

