  if (!state.stream || !state.connected || state.inferenceActive) return;
  state.inferenceActive = true;
  state.responseCount = 0;
  state.fpsWindowStarted = performance.now();
  updateControls();
  log("板端流推理已启动", "success");
  inferOneFrame();
